INSERT INTO `db_script_string` (`entry`,`content_loc8`) VALUES (2000005174,'Вау, это все любовные зелья. Надеюсь он стоит этого.') ON DUPLICATE KEY UPDATE `content_loc8`=IF(`content_loc8` IS NULL OR `content_loc8`='','Вау, это все любовные зелья. Надеюсь он стоит этого.',`content_loc8`);
