INSERT INTO `db_script_string` (`entry`,`content_loc8`) VALUES (2000005176,'Что, если мы использовали три центра в образце Таурена? Это должно решить это.') ON DUPLICATE KEY UPDATE `content_loc8`=IF(`content_loc8` IS NULL OR `content_loc8`='','Что, если мы использовали три центра в образце Таурена? Это должно решить это.',`content_loc8`);
